-- Map every matching existing global card to one canonical row. This mapping
-- is also used to preserve diary and moderation references before duplicates
-- are removed.
CREATE TEMP TABLE globus_catalog_matches ON COMMIT DROP AS
SELECT
    source.normalized_name,
    food.id AS duplicate_id,
    first_value(food.id) OVER (
        PARTITION BY source.normalized_name
        ORDER BY
            (food.barcode <> '') DESC,
            (food.brand_name <> '') DESC,
            food.data_quality DESC,
            food.id
    ) AS canonical_id
FROM globus_catalog_source AS source
JOIN food_catalog AS food
  ON food.owner_user_id IS NULL
 AND regexp_replace(
        translate(lower(trim(food.name)), 'ё«»„“”\"''`', 'е'),
        '[[:space:]]+', '', 'g'
     ) = source.normalized_name;

CREATE INDEX ON globus_catalog_matches (duplicate_id);
CREATE INDEX ON globus_catalog_matches (canonical_id);

-- Before using the reference values from Globus, fill the canonical card from
-- the most complete existing duplicate. Real catalog data remains preferable.
WITH ranked_existing AS (
    SELECT DISTINCT ON (matches.canonical_id)
        matches.canonical_id,
        duplicate.brand_name,
        duplicate.description,
        duplicate.calories_per_100g,
        duplicate.carbohydrate_per_100g,
        duplicate.protein_per_100g,
        duplicate.fat_per_100g,
        duplicate.servings,
        duplicate.data_quality
    FROM globus_catalog_matches AS matches
    JOIN food_catalog AS duplicate ON duplicate.id = matches.duplicate_id
    ORDER BY
        matches.canonical_id,
        (
            duplicate.calories_per_100g = 0
            AND duplicate.carbohydrate_per_100g = 0
            AND duplicate.protein_per_100g = 0
            AND duplicate.fat_per_100g = 0
        ),
        (duplicate.brand_name <> '') DESC,
        duplicate.data_quality DESC,
        (duplicate.barcode <> '') DESC,
        duplicate.id
)
UPDATE food_catalog AS canonical
SET brand_name = CASE
        WHEN trim(canonical.brand_name) = '' THEN ranked.brand_name
        ELSE canonical.brand_name
    END,
    description = CASE
        WHEN trim(canonical.description) = '' THEN ranked.description
        ELSE canonical.description
    END,
    calories_per_100g = CASE
        WHEN canonical.calories_per_100g = 0
         AND canonical.carbohydrate_per_100g = 0
         AND canonical.protein_per_100g = 0
         AND canonical.fat_per_100g = 0
        THEN ranked.calories_per_100g ELSE canonical.calories_per_100g
    END,
    carbohydrate_per_100g = CASE
        WHEN canonical.calories_per_100g = 0
         AND canonical.carbohydrate_per_100g = 0
         AND canonical.protein_per_100g = 0
         AND canonical.fat_per_100g = 0
        THEN ranked.carbohydrate_per_100g ELSE canonical.carbohydrate_per_100g
    END,
    protein_per_100g = CASE
        WHEN canonical.calories_per_100g = 0
         AND canonical.carbohydrate_per_100g = 0
         AND canonical.protein_per_100g = 0
         AND canonical.fat_per_100g = 0
        THEN ranked.protein_per_100g ELSE canonical.protein_per_100g
    END,
    fat_per_100g = CASE
        WHEN canonical.calories_per_100g = 0
         AND canonical.carbohydrate_per_100g = 0
         AND canonical.protein_per_100g = 0
         AND canonical.fat_per_100g = 0
        THEN ranked.fat_per_100g ELSE canonical.fat_per_100g
    END,
    servings = CASE
        WHEN canonical.calories_per_100g = 0
         AND canonical.carbohydrate_per_100g = 0
         AND canonical.protein_per_100g = 0
         AND canonical.fat_per_100g = 0
        THEN ranked.servings ELSE canonical.servings
    END,
    data_quality = greatest(canonical.data_quality, ranked.data_quality),
    cached_at = now()
FROM ranked_existing AS ranked
WHERE canonical.id = ranked.canonical_id;

-- Pick one existing global card per normalized name. A barcode is the strongest
-- signal that the existing card is the canonical, more complete product.
WITH matches AS (
    SELECT
        source.*,
        food.id AS food_id,
        row_number() OVER (
            PARTITION BY source.normalized_name
            ORDER BY
                (food.barcode <> '') DESC,
                (food.brand_name <> '') DESC,
                food.data_quality DESC,
                food.id
        ) AS match_rank
    FROM globus_catalog_source AS source
    JOIN food_catalog AS food
      ON food.owner_user_id IS NULL
     AND regexp_replace(
            translate(lower(trim(food.name)), 'ё«»„“”"''`', 'е'),
            '[[:space:]]+', '', 'g'
         ) = source.normalized_name
), selected AS (
    SELECT * FROM matches WHERE match_rank = 1
)
UPDATE food_catalog AS food
SET brand_name = CASE
        WHEN trim(food.brand_name) = '' THEN selected.brand_name
        ELSE food.brand_name
    END,
    calories_per_100g = CASE
        WHEN food.calories_per_100g = 0
         AND food.carbohydrate_per_100g = 0
         AND food.protein_per_100g = 0
         AND food.fat_per_100g = 0
        THEN selected.calories ELSE food.calories_per_100g
    END,
    carbohydrate_per_100g = CASE
        WHEN food.calories_per_100g = 0
         AND food.carbohydrate_per_100g = 0
         AND food.protein_per_100g = 0
         AND food.fat_per_100g = 0
        THEN selected.carbohydrate ELSE food.carbohydrate_per_100g
    END,
    protein_per_100g = CASE
        WHEN food.calories_per_100g = 0
         AND food.carbohydrate_per_100g = 0
         AND food.protein_per_100g = 0
         AND food.fat_per_100g = 0
        THEN selected.protein ELSE food.protein_per_100g
    END,
    fat_per_100g = CASE
        WHEN food.calories_per_100g = 0
         AND food.carbohydrate_per_100g = 0
         AND food.protein_per_100g = 0
         AND food.fat_per_100g = 0
        THEN selected.fat ELSE food.fat_per_100g
    END,
    servings = CASE
        WHEN food.calories_per_100g = 0
         AND food.carbohydrate_per_100g = 0
         AND food.protein_per_100g = 0
         AND food.fat_per_100g = 0
        THEN jsonb_build_array(jsonb_build_object(
            'id', 'g',
            'description', 'г',
            'metricAmount', 1,
            'metricUnit', 'g',
            'numberOfUnits', 100,
            'measurement', 'г',
            'calories', selected.calories,
            'carbohydrate', selected.carbohydrate,
            'protein', selected.protein,
            'fat', selected.fat
        ))
        ELSE food.servings
    END,
    data_quality = CASE
        WHEN food.calories_per_100g = 0
         AND food.carbohydrate_per_100g = 0
         AND food.protein_per_100g = 0
         AND food.fat_per_100g = 0
        THEN greatest(food.data_quality, 0.65)
        ELSE food.data_quality
    END,
    cached_at = now()
FROM selected
WHERE food.id = selected.food_id;

-- Preserve every reference that can point at a global catalog row. Moderation
-- tables have a unique source key, so keep one record before repointing it.
UPDATE user_nutrition_entries AS entry
SET food_id = matches.canonical_id
FROM globus_catalog_matches AS matches
WHERE entry.food_id = matches.duplicate_id
  AND matches.duplicate_id <> matches.canonical_id;

UPDATE user_food_barcode_links AS link
SET food_id = matches.canonical_id
FROM globus_catalog_matches AS matches
WHERE link.food_id = matches.duplicate_id
  AND matches.duplicate_id <> matches.canonical_id;

UPDATE food_catalog_promotions AS promotion
SET global_food_id = matches.canonical_id
FROM globus_catalog_matches AS matches
WHERE promotion.global_food_id = matches.duplicate_id
  AND matches.duplicate_id <> matches.canonical_id;

WITH ranked AS (
    SELECT
        promotion.source_food_id,
        matches.canonical_id,
        row_number() OVER (
            PARTITION BY matches.canonical_id
            ORDER BY
                (promotion.source_food_id = matches.canonical_id) DESC,
                promotion.promoted_at DESC,
                promotion.source_food_id
        ) AS keep_rank
    FROM food_catalog_promotions AS promotion
    JOIN globus_catalog_matches AS matches
      ON matches.duplicate_id = promotion.source_food_id
)
DELETE FROM food_catalog_promotions AS promotion
USING ranked
WHERE promotion.source_food_id = ranked.source_food_id
  AND ranked.keep_rank > 1;

UPDATE food_catalog_promotions AS promotion
SET source_food_id = matches.canonical_id
FROM globus_catalog_matches AS matches
WHERE promotion.source_food_id = matches.duplicate_id
  AND matches.duplicate_id <> matches.canonical_id;

WITH ranked AS (
    SELECT
        edit.source_food_id,
        matches.canonical_id,
        row_number() OVER (
            PARTITION BY matches.canonical_id
            ORDER BY
                (edit.source_food_id = matches.canonical_id) DESC,
                edit.updated_at DESC,
                edit.source_food_id
        ) AS keep_rank
    FROM food_catalog_review_edits AS edit
    JOIN globus_catalog_matches AS matches
      ON matches.duplicate_id = edit.source_food_id
)
DELETE FROM food_catalog_review_edits AS edit
USING ranked
WHERE edit.source_food_id = ranked.source_food_id
  AND ranked.keep_rank > 1;

UPDATE food_catalog_review_edits AS edit
SET source_food_id = matches.canonical_id
FROM globus_catalog_matches AS matches
WHERE edit.source_food_id = matches.duplicate_id
  AND matches.duplicate_id <> matches.canonical_id;

WITH ranked AS (
    SELECT
        rejection.source_food_id,
        matches.canonical_id,
        row_number() OVER (
            PARTITION BY matches.canonical_id
            ORDER BY
                (rejection.source_food_id = matches.canonical_id) DESC,
                rejection.rejected_at DESC,
                rejection.source_food_id
        ) AS keep_rank
    FROM food_catalog_rejections AS rejection
    JOIN globus_catalog_matches AS matches
      ON matches.duplicate_id = rejection.source_food_id
)
DELETE FROM food_catalog_rejections AS rejection
USING ranked
WHERE rejection.source_food_id = ranked.source_food_id
  AND ranked.keep_rank > 1;

UPDATE food_catalog_rejections AS rejection
SET source_food_id = matches.canonical_id
FROM globus_catalog_matches AS matches
WHERE rejection.source_food_id = matches.duplicate_id
  AND matches.duplicate_id <> matches.canonical_id;

DELETE FROM food_catalog AS duplicate
USING globus_catalog_matches AS matches
WHERE duplicate.id = matches.duplicate_id
  AND matches.duplicate_id <> matches.canonical_id;

-- Only products with no global name match are added. The deterministic ID
-- makes the migration idempotent and keeps later imports stable.
INSERT INTO food_catalog (
    provider, external_id, barcode, name, brand_name, description,
    calories_per_100g, carbohydrate_per_100g, protein_per_100g, fat_per_100g,
    servings, data_quality
)
SELECT
    'community',
    'globus-' || md5(source.normalized_name),
    '',
    source.name,
    source.brand_name,
    'Источник: Глобус. КБЖУ справочные.',
    source.calories,
    source.carbohydrate,
    source.protein,
    source.fat,
    jsonb_build_array(jsonb_build_object(
        'id', 'g',
        'description', 'г',
        'metricAmount', 1,
        'metricUnit', 'g',
        'numberOfUnits', 100,
        'measurement', 'г',
        'calories', source.calories,
        'carbohydrate', source.carbohydrate,
        'protein', source.protein,
        'fat', source.fat
    )),
    0.65
FROM globus_catalog_source AS source
WHERE NOT EXISTS (
    SELECT 1
    FROM food_catalog AS food
    WHERE food.owner_user_id IS NULL
      AND regexp_replace(
            translate(lower(trim(food.name)), 'ё«»„“”"''`', 'е'),
            '[[:space:]]+', '', 'g'
          ) = source.normalized_name
)
ON CONFLICT (provider, external_id) DO UPDATE SET
    name = EXCLUDED.name,
    brand_name = CASE
        WHEN trim(food_catalog.brand_name) = '' THEN EXCLUDED.brand_name
        ELSE food_catalog.brand_name
    END,
    cached_at = now();
